#include <iostream>
#include <vector>

int main() {
  {
    std::vector<int> samples{12, 18, 15};
    samples.push_back(21);
    std::cout << samples.size() << '\n';
  }
  // samples уничтожен: его деструктор освободил хранилище элементов.
}
// vector сам владеет своим хранилищем; отдельный delete[] не нужен.

